/**
 * jQuery Permission 1.0
 * 
 * Author Joe
 */
(function($) {
	$.permission = function() {
		var permissions = ($("#_permission").attr("data") || "").split(",");
		$("[permission]").each(function(j,d) {
			if ($.inArray($(d).attr("permission"), permissions) < 0) {
				$(d).hide();
			}
		});
	};
})(jQuery);
